var isMatch = function(s, p) {
    const m = s.length, n = p.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(false));
    dp[0][0] = true;

    for (let j = 2; j <= n; j++) {
        if (p[j - 1] === '*') {
            dp[0][j] = dp[0][j - 2];
        }
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const token = p[j - 1];
            if (token === '.' || token === s[i - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else if (token === '*' && j >= 2) {
                dp[i][j] = dp[i][j - 2];
                const repeated = p[j - 2];
                if (repeated === '.' || repeated === s[i - 1]) {
                    dp[i][j] = dp[i][j] || dp[i - 1][j];
                }
            }
        }
    }

    return dp[m][n];
};

solution.python:
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True

        for j in range(2, n + 1):
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 2]

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                token = p[j - 1]
                if token == '.' or token == s[i - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                elif token == '*' and j >= 2:
                    dp[i][j] = dp[i][j - 2]
                    repeated = p[j - 2]
                    if repeated == '.' or repeated == s[i - 1]:
                        dp[i][j] = dp[i][j] or dp[i - 1][j]

        return dp[m][n]
